import asyncio
import json
import sys
from typing import Any
from fastmcp import Server
from fastmcp.types import Tool, Resource, TextContent, ToolResult
import httpx


class FastMCPProxy:
    def __init__(self, backend_url: str = "http://localhost:3001"):
        self.backend_url = backend_url
        self.server = Server("mcp-proxy")
        self.client = httpx.AsyncClient(timeout=300.0)
        self.tools_cache: dict[str, Tool] = {}
        self.resources_cache: dict[str, Resource] = {}
        self._initialized = False

    async def initialize(self):
        """Discover tools and resources from backend and register them."""
        if self._initialized:
            return

        try:
            # Discover tools from backend
            response = await self.client.post(
                f"{self.backend_url}/mcp",
                json={"jsonrpc": "2.0", "id": 1, "method": "tools/list", "params": {}},
            )
            tools_data = response.json()
            if "result" in tools_data and "tools" in tools_data["result"]:
                for tool in tools_data["result"]["tools"]:
                    self.tools_cache[tool["name"]] = tool
                    self._register_tool(tool)

            # Discover resources from backend
            response = await self.client.post(
                f"{self.backend_url}/mcp",
                json={"jsonrpc": "2.0", "id": 2, "method": "resources/list", "params": {}},
            )
            resources_data = response.json()
            if "result" in resources_data and "resources" in resources_data["result"]:
                for resource in resources_data["result"]["resources"]:
                    self.resources_cache[resource["uri"]] = resource
                    self._register_resource(resource)
        except Exception as e:
            print(f"Failed to discover backend services: {e}", file=sys.stderr)

        self._initialized = True

    def _register_tool(self, tool: dict[str, Any]):
        """Register a tool from the backend."""
        tool_name = tool["name"]
        tool_description = tool.get("description", "")
        tool_schema = tool.get("inputSchema", {})

        async def tool_handler(**kwargs) -> ToolResult:
            try:
                response = await self.client.post(
                    f"{self.backend_url}/mcp",
                    json={
                        "jsonrpc": "2.0",
                        "id": 3,
                        "method": "tools/call",
                        "params": {"name": tool_name, "arguments": kwargs},
                    },
                )
                result = response.json()
                if "result" in result:
                    return ToolResult(
                        type="text",
                        text=json.dumps(result["result"]),
                    )
                elif "error" in result:
                    return ToolResult(
                        type="text",
                        text=json.dumps({"error": result["error"]}),
                        isError=True,
                    )
            except Exception as e:
                return ToolResult(type="text", text=str(e), isError=True)

        # Dynamically register the tool
        self.server.tool(
            name=tool_name,
            description=tool_description,
        )(tool_handler)

    def _register_resource(self, resource: dict[str, Any]):
        """Register a resource from the backend."""
        resource_uri = resource["uri"]
        resource_name = resource.get("name", resource_uri)
        resource_mime = resource.get("mimeType", "text/plain")

        async def resource_handler() -> TextContent:
            try:
                response = await self.client.post(
                    f"{self.backend_url}/mcp",
                    json={
                        "jsonrpc": "2.0",
                        "id": 4,
                        "method": "resources/read",
                        "params": {"uri": resource_uri},
                    },
                )
                result = response.json()
                if "result" in result and "contents" in result["result"]:
                    content = result["result"]["contents"][0]["text"]
                    return TextContent(
                        type="text",
                        text=content,
                        mimeType=resource_mime,
                    )
            except Exception as e:
                return TextContent(type="text", text=f"Error: {str(e)}")

        # Dynamically register the resource
        self.server.resource(
            uri=resource_uri,
            name=resource_name,
            mimeType=resource_mime,
        )(resource_handler)

    async def run(self, host: str = "localhost", port: int = 3002):
        """Start the proxy server."""
        await self.initialize()
        print(f"Starting MCP proxy on {host}:{port}", file=sys.stderr)
        await self.server.run(host, port)


async def main():
    backend_url = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:3001"
    proxy_port = int(sys.argv[2]) if len(sys.argv) > 2 else 3002

    proxy = FastMCPProxy(backend_url=backend_url)
    await proxy.run(port=proxy_port)


if __name__ == "__main__":
    asyncio.run(main())

